CREATE TABLE IF NOT EXISTS api_prices (team_id VARCHAR(36), provider VARCHAR(32), model VARCHAR(128), effective_from_day BIGINT, input_micros BIGINT NOT NULL, cache_write_micros BIGINT NOT NULL, cache_read_micros BIGINT NOT NULL, output_micros BIGINT NOT NULL, CONSTRAINT pk_api_prices PRIMARY KEY (team_id, provider, model, effective_from_day), CONSTRAINT fk_api_prices_team_id__id FOREIGN KEY (team_id) REFERENCES teams(id) ON DELETE CASCADE ON UPDATE RESTRICT);
